// Generated by Suite Builder from a crawl of the site. Opens the header's dropdowns and follows their links.
// EDIT RULES: edit only inside YOURS blocks; regenerating keeps them and rewrites the rest of this file.
import { Find, shownIn } from './Find';
import type { PageElement } from './PageElement';
import { SiteConfig } from './SiteConfig';
import { WaitActions } from './WaitActions';

/** What opens a dropdown, or part of one; clickToOpen when it is not a real link (a click on one would leave the page). */
export interface Opener {
  element: PageElement;
  clickToOpen: boolean;
}

/**
 * The header's and footer's dropdowns. Each opener is pointed at (the events a menu's script listens
 * for), and clicked too when that isn't enough and it may be clicked. A menu that opens on CSS :hover
 * alone can't be opened by Cypress (it has no real mouse): its link is then clicked where it is,
 * hidden, which follows it all the same.
 */
export const Menus = {
  /** Opens each dropdown the link is in, in order, then clicks the link. */
  click(link: PageElement, openers: Opener[] = []): void {
    openers.forEach((opener, i) => Menus.open(opener, i + 1 < openers.length ? openers[i + 1].element : link));
    cy.document({ log: false }).then((doc) => {
      const $shown = shownIn(doc, link);
      if ($shown.length) return cy.wrap($shown, { log: false }).click();
      return cy.allElements(link).first().click({ force: true });
    });
  },

  /** Like click(), for a link that opens a new tab: Cypress follows it in this one. */
  clickInThisTab(link: PageElement, openers: Opener[] = []): void {
    openers.forEach((opener, i) => Menus.open(opener, i + 1 < openers.length ? openers[i + 1].element : link));
    cy.allElements(link).first().invoke('removeAttr', 'target');
    Menus.click(link);
  },

  /** Points at the opener until what it opens shows; clicks it if it may be clicked and pointing wasn't enough. */
  open(opener: Opener, shows: PageElement): void {
    cy.wrap(null, { log: false }).then(() => {
      if (Find.isVisibleNow(shows)) return;
      cy.document({ log: false }).then((doc) => {
        const $opener = shownIn(doc, opener.element);
        if (!$opener.length) return;
        cy.wrap($opener, { log: false }).trigger('mouseover').trigger('mouseenter');
        cy.wait(1500, { log: false }).then(() => {
          if (!Find.isVisibleNow(shows) && opener.clickToOpen) cy.wrap($opener, { log: false }).click();
        });
      });
    });
  },

  /**
   * For pages the crawl did not read: clicks the link and checks the address it leads to and the page
   * load, telling a click that went nowhere from a link that leads somewhere else.
   */
  follow(link: PageElement, path: string, openers: Opener[] = [], inThisTab = false): void {
    cy.location('href', { log: false }).then((from) => {
      if (inThisTab) Menus.clickInThisTab(link, openers);
      else Menus.click(link, openers);
      Menus.arrive(path, from);
    });
  },

  /** The browser is on the path (checked as the Java suites' arrive() does), and the page has loaded. */
  arrive(path: string, from: string | null): void {
    cy.location('href', { log: false }).should((now) => {
      if (WaitActions.samePage(now, SiteConfig.url(path))) return;
      if (now === from) throw new Error(`The click did not leave the page: still on ${now} (a script may handle this link, e.g. by opening a sign-in window)`);
      throw new Error(`The link to ${path} led to ${now} instead (the link points to an old or moved address, or the site sends it elsewhere)`);
    });
    WaitActions.forPageLoad(); // on its address: a late load event is named, not failed
    WaitActions.noteIfStillLoading(path);
  },
};
